from __future__ import annotations

import html
import json
import re
import unicodedata
from pathlib import Path

from .config import PAGES_BASE_PATH, SITE_BASE_URL
from .export import write_text_atomic

# One static page per Bundesland, regenerated by every full build.
#
# Why they exist: the map is a single URL for two countries, so search demand
# shaped like "Wickeltisch Bayern" has nothing to match — the place names live
# inside a 2.6 MB geojson that crawlers read as a download, not as text. These
# pages put the counts and the names into HTML.
#
# German only, and deliberately: the audience searching for a Wickeltisch in
# Hessen searches in German. That is also why they carry no hreflang alternates
# — same reasoning as impressum.html and datenschutz.html.
#
# Unlike index.html, these files are rewritten nightly, so hard-coded counts in
# the copy, the meta description and the JSON-LD are safe here — the "no counts
# in the markup" rule on the homepage is about hand-maintained files that rot.

GERMAN_MONTHS = ("Januar", "Februar", "März", "April", "Mai", "Juni", "Juli",
                 "August", "September", "Oktober", "November", "Dezember")

# ä→ae rather than ä→a: "baden-wuerttemberg" is the spelling German readers and
# German keyboards produce, and the slug is a public URL we have to keep stable.
_TRANSLIT = str.maketrans({
    "ä": "ae", "ö": "oe", "ü": "ue", "ß": "ss",
    "Ä": "Ae", "Ö": "Oe", "Ü": "Ue",
})

# The amenity tag is a controlled OSM vocabulary, so a lookup table can cover
# it: these 20 values are 99% of the German dataset. Anything else falls back to
# the raw value with underscores stripped — a page that reads half-German is
# better than one that silently drops the type. `null` (a shop, most often a dm
# or Rossmann) has no amenity at all and renders as an em dash.
AMENITY_DE = {
    "toilets": "Öffentliche Toilette",
    "restaurant": "Restaurant",
    "cafe": "Café",
    "fast_food": "Imbiss",
    "community_centre": "Bürgerhaus",
    "library": "Bibliothek",
    "fuel": "Tankstelle",
    "pub": "Kneipe",
    "biergarten": "Biergarten",
    "ice_cream": "Eisdiele",
    "social_facility": "Soziale Einrichtung",
    "townhall": "Rathaus",
    "doctors": "Arztpraxis",
    "pharmacy": "Apotheke",
    "place_of_worship": "Kirche",
    "cinema": "Kino",
    "theatre": "Theater",
    "hospital": "Krankenhaus",
    "marketplace": "Marktplatz",
    "kindergarten": "Kindergarten",
}

# The pages sit one directory below the site root (PAGES_BASE_PATH), so this
# reaches the map, the methods page and the legal pages. Relative on purpose:
# only the canonical and the JSON-LD breadcrumb have to be absolute, and
# relative links mean a page renders and navigates correctly off a local
# `python3 -m http.server -d web` too.
UP = "../"

STATUS_ORDER = ("accessible", "female_only", "unknown")
STATUS_DE = {
    "accessible": "Erreichbar",
    "female_only": "Nur Damen-WC",
    "unknown": "Raum unbekannt",
}
STATUS_CLASS = {"accessible": "g", "female_only": "r", "unknown": "u"}


def slugify(name: str) -> str:
    """URL slug for a Bundesland. The 16 names are a fixed list, so this only
    has to be correct for them — but it is a function rather than a hand-written
    table so a name and its slug cannot drift apart (test_pages pins all 16)."""
    s = name.translate(_TRANSLIT).lower()
    return re.sub(r"[^a-z0-9]+", "-", s).strip("-")


def sort_key(name: str) -> tuple:
    """Alphabetical order a German reader expects: Ärztehaus next to Apotheke,
    not stranded after Zoo where a raw codepoint sort puts it.

    ä sorts as a here, not as ae — that is DIN 5007-1, the ordering used for
    lists of names, and deliberately NOT the ae the slugs use (those follow the
    phone-book spelling because they are URLs someone might type). Decomposing
    and dropping the combining marks generalises it to the é and å that OSM
    names in a German Land do contain."""
    folded = unicodedata.normalize("NFKD", name.replace("ß", "ss").casefold())
    stripped = "".join(c for c in folded if not unicodedata.combining(c))
    return (stripped, name)


def de_num(n) -> str:
    """1234567 → '1.234.567'. The pages are German; the strip on the homepage
    already uses de-DE separators via toLocaleString."""
    return f"{int(n):,}".replace(",", ".")


def de_date(iso: str) -> str:
    """'2026-08-04T21:10:40+00:00' → '4. August 2026'. Hand-rolled because
    strftime('%B') follows the process locale, which on the server is C."""
    try:
        y, m, d = int(iso[0:4]), int(iso[5:7]), int(iso[8:10])
        return f"{d}. {GERMAN_MONTHS[m - 1]} {y}"
    except (ValueError, IndexError, TypeError):
        return ""


def amenity_label(amenity) -> str:
    if not amenity:
        return "—"
    return AMENITY_DE.get(amenity, str(amenity).replace("_", " "))


def group_by_area(features, area_by_key) -> dict:
    """Split the deduped feature list by the sweep area each object came from.

    `area_by_key` is {(osm_type, osm_id): area_name}, recorded while sweeping —
    the geojson itself carries no region field, and the Overpass area query is
    the only authority on which Land an object sits in. An object on a Länder
    boundary is returned by two sweeps and lands in the first one, matching how
    dedup_elements() keeps the first copy for the map."""
    out: dict[str, list] = {}
    for f in features:
        p = f["properties"]
        area = area_by_key.get((p["osm_type"], p["osm_id"]))
        if area is not None:
            out.setdefault(area, []).append(f)
    return out


def _bbox(features) -> list | None:
    """Feature bbox, padded, for the map deep link. Data-driven rather than a
    hard-coded Land box: the features come out of that Land's own area query, so
    their extent is inside it by construction and never needs maintaining. The
    minimum span keeps a Land with a single place from producing a zero-width
    box that fitBounds turns into a maximum-zoom view of one pin."""
    if not features:
        return None
    lons = [f["geometry"]["coordinates"][0] for f in features]
    lats = [f["geometry"]["coordinates"][1] for f in features]
    min_lon, max_lon, min_lat, max_lat = min(lons), max(lons), min(lats), max(lats)
    pad_lon = max((max_lon - min_lon) * 0.04, 0.05)
    pad_lat = max((max_lat - min_lat) * 0.04, 0.03)
    return [round(min_lon - pad_lon, 4), round(min_lat - pad_lat, 4),
            round(max_lon + pad_lon, 4), round(max_lat + pad_lat, 4)]


def summarize(name: str, features, toilets_total: int) -> dict:
    """Everything one Land page needs, computed from that Land's features.

    Named places are grouped by name: the dataset holds 181 shops called "dm"
    and 62 McDonald's, and 181 identical rows would read as generated filler
    rather than as data. The count carries the same information in one row."""
    status_counts = {s: 0 for s in STATUS_ORDER}
    groups: dict[str, dict] = {}
    unnamed = 0
    for f in features:
        p = f["properties"]
        status = p.get("status")
        if status in status_counts:
            status_counts[status] += 1
        place = (p.get("name") or "").strip()
        if not place:
            unnamed += 1
            continue
        g = groups.setdefault(place, {"name": place, "count": 0, "amenities": {},
                                      "statuses": {s: 0 for s in STATUS_ORDER}})
        g["count"] += 1
        if status in g["statuses"]:
            g["statuses"][status] += 1
        a = p.get("amenity")
        g["amenities"][a] = g["amenities"].get(a, 0) + 1
    named = []
    for g in sorted(groups.values(), key=lambda g: sort_key(g["name"])):
        # A chain can carry different amenity values across branches (café vs
        # fast_food); the most common one describes the group honestly enough,
        # and ties break on the value so the page is byte-stable between runs.
        top = sorted(g["amenities"].items(), key=lambda kv: (-kv[1], str(kv[0])))[0][0]
        named.append({"name": g["name"], "count": g["count"],
                      "amenity": top, "statuses": g["statuses"]})
    return {
        "name": name,
        "slug": slugify(name),
        "tables": len(features),
        "accessible": status_counts["accessible"],
        "female_only": status_counts["female_only"],
        "unknown": status_counts["unknown"],
        "toilets_total": toilets_total,
        "named": named,
        "named_places": len(features) - unnamed,
        "unnamed": unnamed,
        "bbox": _bbox(features),
    }


# ---- Rendering -------------------------------------------------------------
# Place names, amenity values and every other interpolated string originate in
# OpenStreetMap, which anyone can edit — so every one of them goes through
# esc(). The surrounding markup is a constant in this file.

def esc(s) -> str:
    return html.escape(str(s), quote=True)


def _jsonld(obj) -> str:
    """A <script> block's content is raw text, so HTML-escaping is exactly the
    wrong tool there (&quot; would land literally and break the JSON). json
    encodes it; escaping "</" is what stops any value from closing the tag."""
    body = json.dumps(obj, ensure_ascii=False).replace("</", "<\\/")
    return f'<script type="application/ld+json">{body}</script>\n\n'


# The same mark index.html carries, inlined for the same reason: a data URI
# costs no request and — unlike a root-relative /icon.svg — resolves from any
# directory depth, so the pages under wickeltische/ need no {up} dance. Without
# it a browser falls back to /favicon.ico, which this site does not serve: every
# generated page logged a 404 until 2026-08-17.
ICON = (
    '<link rel="icon" href="data:image/svg+xml,'
    "%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'%3E"
    "%3Ccircle cx='12' cy='12' r='11' fill='%23009e73'/%3E"
    "%3Crect x='5' y='12' width='14' height='2.6' rx='1.3' fill='%23fff'/%3E"
    "%3Ccircle cx='9' cy='9' r='2.2' fill='%23fff'/%3E"
    "%3Crect x='11.5' y='7.8' width='6.5' height='2.4' rx='1.2' fill='%23fff'/%3E"
    '%3C/svg%3E">'
)

