FOOTER = """\
<h2>Daten &amp; Lizenz</h2>
<p class="muted">Alle Daten &copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap
contributors</a>, unter der <a href="https://opendatacommons.org/licenses/odbl/">ODbL</a>. Diese
Seite wird jede Nacht aus einer Overpass-Abfrage neu erzeugt und speichert nichts über dich.
Wie gezählt und eingefärbt wird: <a href="{up}methods.html">Methoden</a> ·
<a href="{up}impressum.html">Impressum</a> ·
<a href="{up}datenschutz.html">Datenschutz</a></p>
<p class="muted">PapaMap ist kostenlos und werbefrei.
<a href="https://ko-fi.com/jakubwaller">&#9749; Kaffee spendieren</a>.</p>
"""


def _head(title: str, description: str, canonical: str) -> str:
    return f"""<!DOCTYPE html>
<html lang="de">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{esc(title)}</title>
<meta name="description" content="{esc(description)}">
<link rel="canonical" href="{esc(canonical)}">
{ICON}
<style>
{STYLE}</style>
</head>
<body>
"""


def _status_cells(counts) -> str:
    """The three status columns. A zero renders as a muted dash: in a 300-row
    table a column of "0"s is noise that hides the numbers that aren't zero."""
    out = []
    for s in STATUS_ORDER:
        n = counts.get(s, 0)
        out.append('<td class="zero">–</td>' if not n else f"<td>{de_num(n)}</td>")
    return "".join(out)


def _status_head() -> str:
    return "".join(
        f'<th><span class="dot {STATUS_CLASS[s]}"></span>{esc(STATUS_DE[s])}</th>'
        for s in STATUS_ORDER)


def _map_link(bbox, label: str) -> str:
    """Deep link into the map at this Land's extent. Without a bbox the map
    would open on the Germany+Denmark home view, which is no answer to
    "where in Hessen" — app.js reads the param and fits those bounds."""
    if not bbox:
        return ""
    q = ",".join(str(v) for v in bbox)
    return f'<p><a class="cta" href="{UP}?bbox={esc(q)}">{esc(label)} &rarr;</a></p>\n'


def _other_laender(summaries, current_slug: str) -> str:
    items = "".join(
        f'<li><a href="{esc(s["slug"])}.html">{esc(s["name"])}</a> '
        f'<span class="muted">{de_num(s["tables"])} Orte</span></li>'
        for s in summaries if s["slug"] != current_slug)
    return f'<ul class="laender">{items}</ul>\n' if items else ""


def render_land(summary: dict, summaries, generated_at: str,
                base_url: str = SITE_BASE_URL,
                base_path: str = PAGES_BASE_PATH) -> str:
    name, slug = summary["name"], summary["slug"]
    tables, unknown = summary["tables"], summary["unknown"]
    pct = round(100 * unknown / tables) if tables else 0
    date = de_date(generated_at)
    canonical = f"{base_url}{base_path}{slug}.html"
    title = f"Wickeltische in {name} — PapaMap"
    desc = (f"{de_num(tables)} Orte in {name} mit Wickeltisch, aus OpenStreetMap. "
            f"Bei {de_num(unknown)} davon ist nicht erfasst, in welchem Raum der "
            f"Tisch steht — und genau das lässt sich reparieren.")

    parts = [_head(title, desc, canonical)]
    # Breadcrumbs are the one bit of structured data that earns its place here:
    # they tell Google these are the leaves of one section, not 16 loose pages.
    parts.append(_jsonld({
        "@context": "https://schema.org", "@type": "BreadcrumbList",
        "itemListElement": [
            {"@type": "ListItem", "position": 1, "name": "PapaMap",
             "item": f"{base_url}/"},
            {"@type": "ListItem", "position": 2,
             "name": "Wickeltische nach Bundesland",
             "item": f"{base_url}{base_path}"},
            {"@type": "ListItem", "position": 3, "name": name, "item": canonical},
        ],
    }))
    parts.append('<p class="back"><a href="./">&larr; Alle Bundesländer</a> · '
                 f'<a href="{UP}">Zur Karte</a></p>\n')
    parts.append(f"<h1>Wickeltische in {esc(name)}</h1>\n")
    parts.append(f'<p class="muted">Stand {esc(date)} · Daten aus OpenStreetMap</p>\n')

    if not tables:
        # Never reached with real data (every Land has hundreds), but a page
        # claiming "0 Orte, davon 0%" would be worse than one saying so plainly.
        parts.append(f"<p>OpenStreetMap kennt in {esc(name)} derzeit keinen einzigen "
                     "Ort mit Wickeltisch. Das heißt fast sicher: es hat ihn noch "
                     "niemand erfasst.</p>\n")
    else:
        parts.append(
            f"<p>OpenStreetMap kennt in {esc(name)} <strong>{de_num(tables)}</strong> Orte "
            f"mit Wickeltisch. Bei <strong>{de_num(summary['accessible'])}</strong> ist "
            "erfasst, dass ein Vater ihn auch erreicht — Herren-WC, Unisex-WC oder "
            f"eigener Wickelraum. <strong>{de_num(summary['female_only'])}</strong> hängen "
            "nur im Damen-WC. Und bei "
            f"<strong>{de_num(unknown)}</strong> von {de_num(tables)} "
            f"({pct}&nbsp;%) hat schlicht niemand erfasst, in welchem Raum der Tisch "
            "steht. Das sind die grauen Pins auf der Karte, und die sind die "
            "eigentliche Aufgabe: die Frage beantwortet man vor Ort in unter einer "
            "Minute.</p>\n")

    parts.append(_map_link(summary["bbox"], f"{name} auf der Karte öffnen"))

    parts.append(f"<h2>Die Zahlen für {esc(name)}</h2>\n")
    parts.append('<table>\n<tr><th class="l">Wickeltische</th><th>Orte</th></tr>\n')
    for s in STATUS_ORDER:
        parts.append(f'<tr><td class="l"><span class="dot {STATUS_CLASS[s]}"></span>'
                     f'{esc(STATUS_DE[s])}</td><td>{de_num(summary[s])}</td></tr>\n')
    parts.append(f'<tr><td class="l"><strong>Gesamt</strong></td>'
                 f"<td><strong>{de_num(tables)}</strong></td></tr>\n</table>\n")
    parts.append(
        f'<p class="muted">In {esc(name)} sind außerdem '
        f"{de_num(summary['toilets_total'])} öffentliche Toiletten erfasst — die "
        "allermeisten ohne jede Angabe zum Wickeltisch. Ein Versorgungsvergleich "
        "zwischen Ländern lässt sich daraus nicht bauen; warum nicht, steht in den "
        f'<a href="{UP}methods.html">Methoden</a>.</p>\n')

    if summary["named"]:
        parts.append("<h2>Orte mit Namen</h2>\n")
        parts.append(
            f"<p>{de_num(summary['named_places'])} der {de_num(tables)} Orte tragen in "
            f"OpenStreetMap einen Namen, zusammen "
            f"{de_num(len(summary['named']))} verschiedene. Die übrigen "
            f"{de_num(summary['unnamed'])} sind fast durchweg öffentliche Toiletten ohne "
            "Namen — sie stehen auf der Karte, lassen sich hier aber nicht sinnvoll "
            "auflisten. Filialen einer Kette sind zu einer Zeile zusammengefasst.</p>\n")
        parts.append('<div class="scroll">\n<table>\n')
        parts.append(f'<tr><th class="l">Ort</th><th class="l">Art</th><th>Orte</th>'
                     f"{_status_head()}</tr>\n")
        for g in summary["named"]:
            parts.append(
                f'<tr><td class="l">{esc(g["name"])}</td>'
                f'<td class="l">{esc(amenity_label(g["amenity"]))}</td>'
                f'<td>{de_num(g["count"])}</td>{_status_cells(g["statuses"])}</tr>\n')
        parts.append("</table>\n</div>\n")

    parts.append("<h2>Wie du hier hilfst</h2>\n")
    parts.append(
        "<p>Ein grauer Pin heißt: den Wickeltisch gibt es, aber niemand hat erfasst, in "
        "welchem Raum er steht. Genau diese Antwort fehlt Vätern. Beantworten kann sie "
        "jeder mit einem kostenlosen OpenStreetMap-Konto, vor Ort, in unter einer "
        "Minute — der Link am Pin öffnet MapComplete direkt am richtigen Objekt. Die "
        "Antwort landet in OpenStreetMap, gehört allen und ist nach dem nächsten "
        f'nächtlichen Update hier zu sehen. <a href="{UP}methods.html#contribute">'
        "Schritt für Schritt</a>.</p>\n")

    parts.append("<h2>Andere Bundesländer</h2>\n")
    parts.append(_other_laender(summaries, slug))
    parts.append(FOOTER.format(up=UP))
    parts.append("\n</body>\n</html>\n")
    return "".join(parts)


def render_index(summaries, generated_at: str, base_url: str = SITE_BASE_URL,
                 base_path: str = PAGES_BASE_PATH) -> str:
    total = sum(s["tables"] for s in summaries)
    unknown = sum(s["unknown"] for s in summaries)
    date = de_date(generated_at)
    canonical = f"{base_url}{base_path}"
    desc = (f"Wickeltische in Deutschland nach Bundesland: {de_num(total)} Orte aus "
            f"OpenStreetMap, bei {de_num(unknown)} davon ist der Raum nicht erfasst.")

    parts = [_head("Wickeltische nach Bundesland — PapaMap", desc, canonical)]
    parts.append(f'<p class="back"><a href="{UP}">&larr; Zur Karte</a> · '
                 '<a href="rangliste.html">Rangliste</a></p>\n')
    parts.append("<h1>Wickeltische nach Bundesland</h1>\n")
    parts.append(f'<p class="muted">Stand {esc(date)} · Daten aus OpenStreetMap</p>\n')
    parts.append(
        f"<p>OpenStreetMap kennt in Deutschland <strong>{de_num(total)}</strong> Orte mit "
        f"Wickeltisch. Bei <strong>{de_num(unknown)}</strong> davon ist nicht erfasst, in "
        "welchem Raum der Tisch steht — ob ein Vater also überhaupt an ihn herankommt. "
        "Pro Bundesland aufgeschlüsselt:</p>\n")
    parts.append('<div class="scroll">\n<table>\n')
    parts.append(f'<tr><th class="l">Bundesland</th><th>Orte</th>{_status_head()}'
                 "<th>Toiletten</th></tr>\n")
    for s in summaries:
        parts.append(
            f'<tr><td class="l"><a href="{esc(s["slug"])}.html">{esc(s["name"])}</a></td>'
            f'<td>{de_num(s["tables"])}</td>'
            f"{_status_cells({k: s[k] for k in STATUS_ORDER})}"
            f'<td>{de_num(s["toilets_total"])}</td></tr>\n')
    parts.append("</table>\n</div>\n")
    parts.append(
        '<p class="muted">Alphabetisch, nicht nach Anzahl sortiert. Eine Rangliste wäre '
        "irreführend: die Zahlen messen, wie gründlich in einem Land gemappt wurde, nicht "
        "wie gut es mit Wickeltischen versorgt ist. Dieselbe Einschränkung wie beim "
        f'Städtevergleich in den <a href="{UP}methods.html">Methoden</a>. Was sich '
        "ehrlich vergleichen lässt, ist die Veränderung — die steht auf der "
        '<a href="rangliste.html">Rangliste</a>. Die '
        "Spalte <em>Toiletten</em> zählt alle erfassten öffentlichen Toiletten, mit oder "
        "ohne Wickeltisch.</p>\n")
    parts.append(FOOTER.format(up=UP))
    parts.append("\n</body>\n</html>\n")
    return "".join(parts)


def write_pages(summaries, out_dir: str, generated_at: str,
                base_url: str = SITE_BASE_URL,
                base_path: str = PAGES_BASE_PATH) -> list:
    """Write index + one page per Land. Written last in the build and one file
    at a time (atomically each), so a crash leaves the previous night's pages
    served rather than a half-written one."""
    written = []
    for s in summaries:
        path = str(Path(out_dir) / f"{s['slug']}.html")
        write_text_atomic(render_land(s, summaries, generated_at, base_url, base_path), path)
        written.append(path)
    path = str(Path(out_dir) / "index.html")
    write_text_atomic(render_index(summaries, generated_at, base_url, base_path), path)
    written.append(path)
    return written
